import RNA, random, sys, time
from multiprocessing import Pool

target = "......((.......((.((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...........((...............)).)).......)).)).......))......"
n = len(target)
pt = RNA.ptable(target)
pairs = []
for i in range(1, len(pt)):
    j = pt[i-1]-1
    if j > i-1:
        pairs.append((i-1, j))
pairset = set(pairs)

helices = []
used = set()
for (i,j) in sorted(pairs):
    if (i,j) in used: continue
    h=[(i,j)]; used.add((i,j))
    ci,cj=i+1,j-1
    while (ci,cj) in pairset:
        h.append((ci,cj)); used.add((ci,cj)); ci+=1; cj-=1
    helices.append(h)

def init_seq(seed):
    r = random.Random(seed)
    seq = ['A']*n
    for h in helices:
        for idx,(i,j) in enumerate(h):
            if idx%2==0: seq[i]='G'; seq[j]='C'
            else: seq[i]='C'; seq[j]='G'
    for h in helices:
        ii,ij=h[-1]
        enclosed=[(a,b) for (a,b) in pairs if a>ii and b<ij]
        if not enclosed:
            seq[ii+1]='G'; seq[ii+2]='A'; seq[ii+3]='A'; seq[ii+4]='A'
    # random kick
    for _ in range(r.randint(5,40)):
        p=r.randint(0,n-1); seq[p]=r.choice('ACGU')
    return seq

def fold_ss(s):
    fc=RNA.fold_compound(s); ss,_=fc.mfe(); return ss
def bp_dist(ss): return RNA.bp_distance(ss, target)

def diagnose(ss):
    ss_pt = RNA.ptable(ss)
    issues = []
    for (i,j) in pairs:
        if ss_pt[i]-1 != j+1:
            issues.append(('missing',i,j))
    for k in range(1,len(ss_pt)):
        m = ss_pt[k-1]-1
        if m>0 and (k-1,m) not in pairset and (m,k-1) not in pairset:
            issues.append(('spurious',k-1,m))
    return issues

def worker(seed):
    r = random.Random(seed*7919+1)
    cur = init_seq(seed)
    cur_d = bp_dist(fold_ss(''.join(cur)))
    best = cur[:]; best_d = cur_d
    t0=time.time()
    T = 4.0
    while time.time()-t0 < 250 and best_d > 0:
        cand = cur[:]
        ss_c = fold_ss(''.join(cand))
        issues = diagnose(ss_c)
        if issues and r.random()<0.8:
            issue = r.choice(issues)
            if issue[0]=='missing':
                i,j = issue[1],issue[2]
                cand[i]='G'; cand[j]='C'
                if r.random()<0.3:
                    pp = r.choice([i,j]) + r.choice([-1,1])
                    if 0<=pp<n: cand[pp]=r.choice('ACGU')
            else:
                i,j = issue[1],issue[2]
                cand[i]=r.choice(['A','U']); cand[j]=r.choice(['A','U'])
        for _ in range(r.randint(0,2)):
            p=r.randint(0,n-1); cand[p]=r.choice('ACGU')
        cs = bp_dist(fold_ss(''.join(cand)))
        delta = cs - cur_d
        if delta <= 0 or r.random() < pow(2.718, -delta/max(T,0.05)):
            cur=cand[:]; cur_d=cs
            if cs < best_d:
                best_d=cs; best=''.join(cand)
        T *= 0.9998
    return (best_d, ''.join(best))

if __name__=='__main__':
    t0=time.time()
    seeds = list(range(40))
    with Pool(32) as p:
        results = p.map(worker, seeds)
    results.sort(key=lambda x: x[0])
    print("best d=", results[0][0], "time", time.time()-t0, flush=True)
    print(results[0][1], flush=True)
